#include <cstddef>
#include <iostream>
#include <memory>
#include <new>

class Arena {
public:
    Arena(std::byte* data, std::size_t capacity)
        : begin_(data), capacity_(capacity) {}

    void* allocate(std::size_t bytes, std::size_t alignment) {
        void* candidate = begin_ + used_;
        std::size_t space = capacity_ - used_;
        void* aligned = std::align(alignment, bytes, candidate, space);
        if (aligned == nullptr) {
            throw std::bad_alloc{};
        }
        used_ = static_cast<std::byte*>(aligned) - begin_ + bytes;
        return aligned;
    }

    std::size_t used() const noexcept { return used_; }
    void reset() noexcept { used_ = 0; }

private:
    std::byte* begin_;
    std::size_t capacity_;
    std::size_t used_{};
};

int main() {
    alignas(64) std::byte scratch[256];
    Arena arena{scratch, sizeof(scratch)};

    arena.allocate(1, 1);
    std::cout << arena.used() << ' ';

    arena.allocate(8, 8);
    std::cout << arena.used() << ' ';

    arena.reset();
    std::cout << arena.used() << '\n';
}

