#include <iostream>
#include <memory>
#include <new>

struct Order {
    int id;
    double price;

    Order(int order_id, double order_price)
        : id(order_id), price(order_price) {}
};

void run_once(int id, double price) {
    void* storage = ::operator new(sizeof(Order));  // allocation only

    Order* order = nullptr;
    try {
        // construction + initialization
        order = std::construct_at(static_cast<Order*>(storage), id, price);
    } catch (...) {
        ::operator delete(storage);  // no object was created; return the bytes
        throw;
    }

    std::cout << order->id << ' ' << order->price << '\n';

    std::destroy_at(order);      // lifetime ends; the bytes remain
    ::operator delete(storage);  // deallocation
}

#include <cstddef>

struct Order {
    int id{};
    double price{};
};

Order* make_batch(std::size_t count) {
    // Array new-expression: one allocation, `count` element lifetimes begun.
    return new Order[count]{};
}

void release_batch(Order* batch) noexcept {
    // Must be delete[], not delete: the scalar form may read the wrong
    // metadata or run the wrong number of destructors.
    //
    // Undefined behaviour from the chapter's table:
    //   new T      released with std::free
    //   std::malloc released with delete
    //   new T[n]   released with delete
    //
    // No null check is needed: delete[] nullptr is a valid no-op.
    delete[] batch;
}

#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <limits>

struct Tick {
    std::uint64_t sequence;
    std::int64_t price_ticks;
};

bool grow(Tick*& ticks, std::size_t& capacity, std::size_t new_capacity) {
    if (new_capacity <= capacity) {
        return true;
    }
    // std::size_t arithmetic wraps, so check before multiplying.
    if (new_capacity > std::numeric_limits<std::size_t>::max() / sizeof(Tick)) {
        return false;
    }

    // Keep the old pointer until success is known: a failing realloc returns
    // nullptr and leaves the original block allocated and still ours.
    void* grown = std::realloc(ticks, new_capacity * sizeof(Tick));
    if (grown == nullptr) {
        return false;
    }

    // On success the old pointer is invalid even if the address compares
    // equal; every interior pointer, reference and iterator is invalidated.
    ticks = static_cast<Tick*>(grown);
    capacity = new_capacity;
    return true;
}

#include <iostream>
#include <new>

struct Order {
    int id;
    double price;

    Order(int order_id, double order_price)
        : id(order_id), price(order_price) {}
};

// std::nothrow replaces the std::bad_alloc path with a nullable result.
// It does not remove failure handling, and it does not stop a constructor
// exception from propagating out of the new-expression.
bool acquire_or_null(int id, double price) {
    Order* order = new (std::nothrow) Order{id, price};
    if (order == nullptr) {
        return false;
    }

    std::cout << order->id << '\n';
    delete order;
    return true;
}

bool acquire_or_throw(int id, double price) {
    try {
        Order* order = new Order{id, price};
        std::cout << order->id << '\n';
        delete order;
        return true;
    } catch (const std::bad_alloc&) {
        return false;
    }
}

