#include <utility>

template<class T>
class Deferred {
public:
    Deferred() = default;
    ~Deferred() { reset(); }

    Deferred(const Deferred&) = delete;
    Deferred& operator=(const Deferred&) = delete;

    template<class... Args>
    T* emplace(Args&&... args) {
        reset();
        object_ = std::construct_at(
            reinterpret_cast<T*>(storage_), std::forward<Args>(args)...);
        return object_;
    }

    T* get() noexcept { return object_; }          // null while not alive
    bool alive() const noexcept { return object_ != nullptr; }

    void reset() noexcept {
        if (object_ != nullptr) {
            std::destroy_at(object_);
            object_ = nullptr;
        }
    }

private:
    alignas(T) std::byte storage_[sizeof(T)];
    T* object_ = nullptr;
};

#include <cstddef>
#include <cstdlib>
#include <new>

std::size_t pooled_allocations = 0;

class OrderMemory {
public:
    static void* allocate(std::size_t bytes) {
        ++pooled_allocations;
        if (void* pointer = std::malloc(bytes)) {
            return pointer;
        }
        throw std::bad_alloc{};
    }

    static void deallocate(void* pointer) noexcept { std::free(pointer); }
};

struct PooledOrder {
    int id;
    double price;

    // `bytes` can exceed sizeof(PooledOrder): a derived class inherits these
    // functions and a derived object is generally larger. Serve the request
    // as given rather than assuming a fixed size.
    static void* operator new(std::size_t bytes) {
        return OrderMemory::allocate(bytes);
    }

    static void operator delete(void* pointer) noexcept {
        OrderMemory::deallocate(pointer);
    }

    // Array allocation is a separate name and needs its own pair.
    static void* operator new[](std::size_t bytes) {
        return OrderMemory::allocate(bytes);
    }

    static void operator delete[](void* pointer) noexcept {
        OrderMemory::deallocate(pointer);
    }
};

#include <cstddef>
#include <cstdlib>
#include <limits>

static bool is_power_of_two(std::size_t value) noexcept {
    return value != 0 && (value & (value - 1)) == 0;
}

void* aligned_block(std::size_t alignment, std::size_t bytes) noexcept {
    if (!is_power_of_two(alignment)) {
        return nullptr;
    }
    if (bytes > std::numeric_limits<std::size_t>::max() - (alignment - 1)) {
        return nullptr;  // rounding would wrap
    }

    // std::aligned_alloc requires the size to be a multiple of the alignment.
    std::size_t rounded = (bytes + alignment - 1) & ~(alignment - 1);

    return std::aligned_alloc(alignment, rounded);  // nullptr on failure
}

void release_block(void* pointer) noexcept {
    std::free(pointer);  // C family in, C family out
}

#include <cstddef>
#include <memory>
#include <new>

class StackAllocator {
public:
    StackAllocator(std::byte* data, std::size_t capacity) noexcept
        : begin_(data), capacity_(capacity) {}

    std::size_t marker() const noexcept { return used_; }

    void* allocate(std::size_t bytes, std::size_t alignment) {
        void* candidate = begin_ + used_;
        std::size_t space = capacity_ - used_;

        void* aligned = std::align(alignment, bytes, candidate, space);
        if (aligned == nullptr) {
            throw std::bad_alloc{};  // explicit exhaustion policy
        }

        used_ = static_cast<std::byte*>(aligned) - begin_ + bytes;
        return aligned;
    }

    // Runs no destructors and checks nothing. The caller must have destroyed
    // every live object allocated above `marker`, and the marker must have
    // come from this allocator: rewinding forward, in non-LIFO order, or with
    // another allocator's offset all fit in a std::size_t and are all
    // contract violations.
    void rewind(std::size_t marker) noexcept { used_ = marker; }

private:
    std::byte* begin_;
    std::size_t capacity_;
    std::size_t used_{};
};
